if python3 registry.py add --slug meet-santa-at-zona-rosa-kansas-city-mo --name 'Meet Santa at Zona Rosa' --city 'Kansas City' --cc mo --url https://www.zonarosa.com/events/events/meet-santa-at-zona-rosa/ --date 2026-11-27 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST meet-santa-at-zona-rosa-kansas-city-mo"; fi || true
