if python3 registry.py add --slug annual-brw-winter-wonderland-holiday-display-kansas-city-mo --name 'Annual BRW Winter Wonderland Holiday Display' --city 'Kansas City' --cc mo --url https://kcparks.org/event/annual-brw-winter-wonderland-holiday-display/ --date 2026-12-01 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST annual-brw-winter-wonderland-holiday-display-kansas-city-mo"; fi || true
