if python3 registry.py add --slug santas-arrival-at-crown-center-kansas-city-mo --name 'Santa'"'"'s Arrival at Crown Center' --city 'Kansas City' --cc mo --url https://www.visitkc.com/events/santas-arrival-at-crown-center/ --date 2026-11-27 --status live --confirm-new; then ADDED=$((ADDED+1)); else REFUSED=$((REFUSED+1)); REFUSED_LIST="$REFUSED_LIST santas-arrival-at-crown-center-kansas-city-mo"; fi || true
